def evaluate(self) -> Dict[str, float]:
    ...
    # Helper: compute observed Rb and churn from microdata if available
    def compute_observed_rb_churn(ts: pd.DataFrame) -> Tuple[List[float], List[float]]:
        if ts is None or ts.empty:
            return [], []
        days_sorted = sorted(ts["day"].unique())
        # Build wide table day x agent for wearing_mask
        pivot = ts.pivot_table(index="day", columns="agent_id", values="wearing_mask", aggfunc="max").fillna(False).astype(bool)
        rb_series_obs, churn_series_obs = [], []
        for idx in range(1, len(days_sorted)):
            d_prev, d_curr = days_sorted[idx-1], days_sorted[idx]
            prev = pivot.loc[d_prev].values
            curr = pivot.loc[d_curr].values
            active_prev = int(prev.sum())
            new_adopt = int(((~prev) & curr).sum())
            drops = int((prev & (~curr)).sum())
            rb = (new_adopt / active_prev) if active_prev > 0 else 0.0
            churn = (drops / active_prev) if active_prev > 0 else 0.0
            rb_series_obs.append(rb)
            churn_series_obs.append(churn)
        return rb_series_obs, churn_series_obs
    rb_obs, churn_obs = compute_observed_rb_churn(self.timeseries_df)
    # Build day-indexed observed adoption if available
    obs_by_day = getattr(self, "observed_adoption_series_by_day", None)
    start = int(self.params.get("prediction_start_day", 30))
    end = int(self.params.get("prediction_end_day", 39))
    for metric in metrics_list:
        if metric == "RMSE":
            if obs_by_day:
                days = [d for d in range(start, end + 1) if d < len(sim_adoption) and d in obs_by_day]
                if days:
                    y_true = [obs_by_day[d] for d in days]
                    y_pred = [sim_adoption[d] for d in days]
                    results["RMSE"] = rmse(y_true, y_pred)
                else:
                    results["RMSE"] = float("nan")
            else:
                results["RMSE"] = float("nan")
        elif metric == "TimeTo50Error":
            if obs_by_day:
                t_obs = next((d for d in range(start, end + 1) if obs_by_day.get(d, -1) >= 0.5), None)
                t_sim = next((d for d, v in enumerate(sim_adoption) if v >= 0.5), None)
                results["TimeTo50Error"] = abs(int(t_obs) - int(t_sim)) if (t_obs is not None and t_sim is not None) else float("nan")
            else:
                results["TimeTo50Error"] = float("nan")
        elif metric == "Rb_MAE":
            # Compare over overlapping internal window length
            if rb_obs and self.aggregator and self.aggregator.Rb_series:
                L = min(len(rb_obs), len(self.aggregator.Rb_series)-1)  # sim Rb starts after w window; be conservative
                results["Rb_MAE"] = mae(rb_obs[:L], self.aggregator.Rb_series[1:1+L]) if L > 0 else float("nan")
            else:
                results["Rb_MAE"] = float("nan")
        elif metric == "Churn_MAE":
            if churn_obs and self.aggregator and self.aggregator.churn_rate_daily:
                L = min(len(churn_obs), len(self.aggregator.churn_rate_daily)-1)
                results["Churn_MAE"] = mae(churn_obs[:L], self.aggregator.churn_rate_daily[1:1+L]) if L > 0 else float("nan")
            else:
                results["Churn_MAE"] = float("nan")
        else:
            results[metric] = float("nan")

